extends RefCounted

func run() -> int:
	var base_size := Vector2(1152, 648)
	var window_size := Vector2(1920, 1080)
	var scale_factor: float = minf(window_size.x / base_size.x, window_size.y / base_size.y)
	var effective_width: float = base_size.x * scale_factor
	var total_black_bars_px: float = window_size.x - effective_width
	return int(total_black_bars_px)

extends RefCounted

func run() -> float:
	var base_size := Vector2(1152, 648)
	var window_size := Vector2(1280, 1024)
	var scale_factor: float = minf(window_size.x / base_size.x, window_size.y / base_size.y)
	var effective_height: float = base_size.y * scale_factor
	var total_letterbox_y: float = window_size.y - effective_height
	return total_letterbox_y
